CREATE TABLE tenant_provider_trust_policies(policy_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),policy_version INTEGER NOT NULL,policy_digest TEXT NOT NULL UNIQUE,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,company_binding_id TEXT NOT NULL,owner_eligibility_id TEXT NOT NULL,owner_authority_id TEXT NOT NULL,effective_at TEXT NOT NULL,expires_at TEXT,issued_at TEXT NOT NULL,supersedes_policy_id TEXT,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL,UNIQUE(tenant_id,company_id,policy_version));
CREATE TABLE tenant_provider_trust_policy_scopes(policy_id TEXT PRIMARY KEY REFERENCES tenant_provider_trust_policies(policy_id),scope_id TEXT NOT NULL,purpose TEXT,classifications_json TEXT NOT NULL,sovereignties_json TEXT NOT NULL,target_classes_json TEXT NOT NULL);
CREATE TABLE tenant_provider_trust_requirements(policy_id TEXT NOT NULL REFERENCES tenant_provider_trust_policies(policy_id),requirement_id TEXT NOT NULL,subject TEXT NOT NULL,requirement_json TEXT NOT NULL,PRIMARY KEY(policy_id,requirement_id),UNIQUE(policy_id,subject));
CREATE TABLE tenant_provider_trust_policy_transitions(transition_id TEXT PRIMARY KEY,policy_id TEXT NOT NULL REFERENCES tenant_provider_trust_policies(policy_id),status TEXT NOT NULL CHECK(status IN('REVOKED','SUPERSEDED','EXPIRED')),reference TEXT NOT NULL UNIQUE,transitioned_at TEXT NOT NULL,correlation_id TEXT NOT NULL);
CREATE TABLE tenant_provider_trust_resolutions(resolution_id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,policy_ids_json TEXT NOT NULL,effective_policy_digest TEXT NOT NULL,context_json TEXT NOT NULL,context_digest TEXT NOT NULL,requirements_json TEXT NOT NULL,resolved_at TEXT NOT NULL);
CREATE TABLE provider_trust_evaluations(evaluation_id TEXT PRIMARY KEY,evaluation_digest TEXT NOT NULL UNIQUE,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,resolved_policy_id TEXT NOT NULL REFERENCES tenant_provider_trust_resolutions(resolution_id),policy_digest TEXT NOT NULL,provider_account_id TEXT NOT NULL,provider_deployment_id TEXT,attestation_set_digest TEXT NOT NULL,context_json TEXT NOT NULL,context_digest TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('SATISFIED','DENIED','INSUFFICIENT_EVIDENCE')),reason_codes_json TEXT NOT NULL,evaluated_at TEXT NOT NULL,expires_at TEXT NOT NULL,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL,stale INTEGER NOT NULL CHECK(stale=0),dispatch_authorized INTEGER NOT NULL CHECK(dispatch_authorized=0));
CREATE TABLE provider_trust_requirement_results(evaluation_id TEXT NOT NULL REFERENCES provider_trust_evaluations(evaluation_id),requirement_id TEXT NOT NULL,subject TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('SATISFIED','DENIED','INSUFFICIENT_EVIDENCE')),reason_code TEXT NOT NULL,attestation_id TEXT,recorded_at TEXT NOT NULL,PRIMARY KEY(evaluation_id,requirement_id));
CREATE TABLE provider_trust_eligibilities(eligibility_id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,policy_digest TEXT NOT NULL,context_digest TEXT NOT NULL,provider_account_id TEXT NOT NULL,provider_deployment_id TEXT,attestation_set_digest TEXT NOT NULL,evaluation_id TEXT NOT NULL UNIQUE REFERENCES provider_trust_evaluations(evaluation_id),evaluation_digest TEXT NOT NULL,allowed_target_class TEXT NOT NULL,future_consumer TEXT NOT NULL CHECK(future_consumer='PT_WU3_RUNTIME_PROVIDER_ADMISSION'),issued_at TEXT NOT NULL,expires_at TEXT NOT NULL,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL);
CREATE TABLE provider_trust_audit_events(audit_event_id TEXT PRIMARY KEY,event_type TEXT NOT NULL,subject_id TEXT NOT NULL,outcome TEXT NOT NULL,correlation_id TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE TRIGGER tenant_provider_policy_immutable BEFORE UPDATE ON tenant_provider_trust_policies BEGIN SELECT RAISE(ABORT,'TENANT_PROVIDER_POLICY_IMMUTABLE');END;CREATE TRIGGER tenant_provider_policy_no_delete BEFORE DELETE ON tenant_provider_trust_policies BEGIN SELECT RAISE(ABORT,'TENANT_PROVIDER_POLICY_IMMUTABLE');END;
CREATE TRIGGER tenant_provider_scope_immutable BEFORE UPDATE ON tenant_provider_trust_policy_scopes BEGIN SELECT RAISE(ABORT,'TENANT_PROVIDER_SCOPE_IMMUTABLE');END;CREATE TRIGGER tenant_provider_scope_no_delete BEFORE DELETE ON tenant_provider_trust_policy_scopes BEGIN SELECT RAISE(ABORT,'TENANT_PROVIDER_SCOPE_IMMUTABLE');END;
CREATE TRIGGER tenant_provider_requirement_immutable BEFORE UPDATE ON tenant_provider_trust_requirements BEGIN SELECT RAISE(ABORT,'TENANT_PROVIDER_REQUIREMENT_IMMUTABLE');END;CREATE TRIGGER tenant_provider_requirement_no_delete BEFORE DELETE ON tenant_provider_trust_requirements BEGIN SELECT RAISE(ABORT,'TENANT_PROVIDER_REQUIREMENT_IMMUTABLE');END;
CREATE TRIGGER tenant_provider_transition_immutable BEFORE UPDATE ON tenant_provider_trust_policy_transitions BEGIN SELECT RAISE(ABORT,'TENANT_PROVIDER_TRANSITION_IMMUTABLE');END;CREATE TRIGGER tenant_provider_transition_no_delete BEFORE DELETE ON tenant_provider_trust_policy_transitions BEGIN SELECT RAISE(ABORT,'TENANT_PROVIDER_TRANSITION_IMMUTABLE');END;
CREATE TRIGGER tenant_provider_resolution_immutable BEFORE UPDATE ON tenant_provider_trust_resolutions BEGIN SELECT RAISE(ABORT,'TENANT_PROVIDER_RESOLUTION_IMMUTABLE');END;CREATE TRIGGER tenant_provider_resolution_no_delete BEFORE DELETE ON tenant_provider_trust_resolutions BEGIN SELECT RAISE(ABORT,'TENANT_PROVIDER_RESOLUTION_IMMUTABLE');END;
CREATE TRIGGER provider_trust_evaluation_immutable BEFORE UPDATE ON provider_trust_evaluations BEGIN SELECT RAISE(ABORT,'PROVIDER_TRUST_EVALUATION_IMMUTABLE');END;CREATE TRIGGER provider_trust_evaluation_no_delete BEFORE DELETE ON provider_trust_evaluations BEGIN SELECT RAISE(ABORT,'PROVIDER_TRUST_EVALUATION_IMMUTABLE');END;
CREATE TRIGGER provider_trust_result_immutable BEFORE UPDATE ON provider_trust_requirement_results BEGIN SELECT RAISE(ABORT,'PROVIDER_TRUST_RESULT_IMMUTABLE');END;CREATE TRIGGER provider_trust_result_no_delete BEFORE DELETE ON provider_trust_requirement_results BEGIN SELECT RAISE(ABORT,'PROVIDER_TRUST_RESULT_IMMUTABLE');END;
CREATE TRIGGER provider_trust_eligibility_immutable BEFORE UPDATE ON provider_trust_eligibilities BEGIN SELECT RAISE(ABORT,'PROVIDER_TRUST_ELIGIBILITY_IMMUTABLE');END;CREATE TRIGGER provider_trust_eligibility_no_delete BEFORE DELETE ON provider_trust_eligibilities BEGIN SELECT RAISE(ABORT,'PROVIDER_TRUST_ELIGIBILITY_IMMUTABLE');END;
CREATE TRIGGER provider_trust_audit_immutable BEFORE UPDATE ON provider_trust_audit_events BEGIN SELECT RAISE(ABORT,'PROVIDER_TRUST_AUDIT_IMMUTABLE');END;CREATE TRIGGER provider_trust_audit_no_delete BEFORE DELETE ON provider_trust_audit_events BEGIN SELECT RAISE(ABORT,'PROVIDER_TRUST_AUDIT_IMMUTABLE');END;
